class Stage {
    constructor(name) {
        this.name = name;
        this.baseSetupMinutes = 60; // Base setup time for any stage
    }

    calculateSetupTime() {
        return this.baseSetupMinutes;
    }
}

class MainStage extends Stage {
    constructor(name, numLights, numScreens) {
        super(name);
        this.numLights = numLights;
        this.numScreens = numScreens;
    }

    calculateSetupTime() {
        let totalTime = super.calculateSetupTime();
        totalTime += this.numLights * 10;
        totalTime += this.numScreens * 15;
        return totalTime;
    }
}

class AcousticStage extends Stage {
    constructor(name, hasPiano, numMics) {
        super(name);
        this.hasPiano = hasPiano;
        this.numMics = numMics;
    }

    calculateSetupTime() {
        let totalTime = super.calculateSetupTime();
        if (this.hasPiano) {
            totalTime += 30;
        }
        totalTime += this.numMics * 5;
        return totalTime;
    }
}

class DJBooth extends Stage {
    constructor(name, numTurntables) {
        super(name);
        this.numTurntables = numTurntables;
    }

    calculateSetupTime() {
        let totalTime = super.calculateSetupTime();
        totalTime += this.numTurntables * 20;
        return totalTime;
    }
}

// Example Usage (for testing)
